IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiExternalDataAuthenticateV2') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0xcc1fc01de6b0b63f0fb99096b07119f0072a603e53d65a06867b8a2f196d2884) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiExternalDataAuthenticateV2')) THROW 59600,'C1 reviewed module drift: AiExternalDataAuthenticateV2.',1;
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiExternalDataAppendAccessV2') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0x760ceadcd21428057c7a07950342da699fdf6f1e02518e009d8788180ee1b74e) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiExternalDataAppendAccessV2')) THROW 59600,'C1 reviewed module drift: AiExternalDataAppendAccessV2.',1;
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiExternalDataAdmitV2') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0x26c5362b3d801b6741b8193a555aac989b708880328f5a022dc58a1912c7f3ed) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiExternalDataAdmitV2')) THROW 59600,'C1 reviewed module drift: AiExternalDataAdmitV2.',1;
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiExternalDataSearchCasesV2') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0x4b840569ee86456d0dad7c07144296eecef6cb6a8ba1236ab719c5103b236b2e) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiExternalDataSearchCasesV2')) THROW 59600,'C1 reviewed module drift: AiExternalDataSearchCasesV2.',1;
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.object_id=OBJECT_ID(N'dbo.AiExternalDataGetCaseOverviewV2') AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND m.execute_as_principal_id IS NULL AND HASHBYTES('SHA2_256',m.definition)=0xeb992340c5318094d558fb7ea401be66402281384e29e3aad39238fa0dc96c28) OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiExternalDataGetCaseOverviewV2')) THROW 59600,'C1 reviewed module drift: AiExternalDataGetCaseOverviewV2.',1;
