V1',N'AiCimdOAuthControlV1',N'CONTROL',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdOAuthReceiptV1',N'SELECT',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdOAuthReceiptV1',N'INSERT',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdOAuthReceiptV1',N'UPDATE',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdOAuthReceiptV1',N'DELETE',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdOAuthReceiptV1',N'ALTER',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdOAuthReceiptV1',N'CONTROL',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAuthorizationV1',N'SELECT',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAuthorizationV1',N'INSERT',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAuthorizationV1',N'UPDATE',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAuthorizationV1',N'DELETE',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAuthorizationV1',N'ALTER',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAuthorizationV1',N'CONTROL',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAssertionReplayV1',N'SELECT',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAssertionReplayV1',N'INSERT',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAssertionReplayV1',N'UPDATE',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAssertionReplayV1',N'DELETE',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAssertionReplayV1',N'ALTER',N'D'),(N'AiCimdOAuthResolverV1',N'AiCimdAssertionReplayV1',N'CONTROL',N'D');
IF EXISTS(SELECT USER_NAME(p.grantee_principal_id) COLLATE Latin1_General_100_BIN2,OBJECT_NAME(p.major_id) COLLATE Latin1_General_100_BIN2,p.permission_name COLLATE Latin1_General_100_BIN2,p.state COLLATE Latin1_General_100_BIN2 FROM sys.database_permissions p WHERE p.grantee_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')) EXCEPT SELECT RoleName,ObjectName,PermissionName,State FROM @C4bPermissions)
 OR EXISTS(SELECT RoleName,ObjectName,PermissionName,State FROM @C4bPermissions EXCEPT SELECT USER_NAME(p.grantee_principal_id) COLLATE Latin1_General_100_BIN2,OBJECT_NAME(p.major_id) COLLATE Latin1_General_100_BIN2,p.permission_name COLLATE Latin1_General_100_BIN2,p.state COLLATE Latin1_General_100_BIN2 FROM sys.database_permissions p WHERE p.grantee_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')))
 OR EXISTS(SELECT 1 FROM sys.database_permissions WHERE grantee_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')) AND (class<>1 OR minor_id<>0 OR grantor_principal_id<>1)) THROW 59500,'CIMD OAuth permission drift.',1;
IF EXISTS(SELECT 1 FROM sys.database_principals WHERE principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')) AND (type<>'R' OR owning_principal_id<>1)) THROW 59500,'CIMD OAuth role ownership drift.',1;
DECLARE @C4bMembers table(Id int PRIMARY KEY);
INSERT @C4bMembers SELECT member_principal_id FROM sys.database_role_members WHERE role_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1'));
IF EXISTS(SELECT 1 FROM sys.database_role_members WHERE member_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')))
 OR EXISTS(SELECT 1 FROM sys.database_role_members WHERE member_principal_id IN(SELECT Id FROM @C4bMembers) AND role_principal_id NOT IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')))
 OR EXISTS(SELECT member_principal_id FROM sys.database_role_members WHERE role_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')) GROUP BY member_principal_id HAVING COUNT(*)<>1)
 OR EXISTS(SELECT 1 FROM sys.database_principals p JOIN @C4bMembers m ON m.Id=p.principal_id WHERE p.type<>'S')
 OR EXISTS(SELECT 1 FROM sys.database_permissions WHERE grantee_principal_id IN(SELECT Id FROM @C4bMembers) AND NOT(class=0 AND state='G' AND permission_name='CONNECT'))
 OR EXISTS(SELECT 1 FROM sys.schemas WHERE principal_id IN(SELECT Id FROM @C4bMembers) OR principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')))
 OR EXISTS(SELECT 1 FROM sys.objects WHERE principal_id IN(SELECT Id FROM @C4bMembers) OR principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')))
 OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id IN(SELECT OBJECT_ID('dbo.'+Name) FROM @C4bObjects))
 THROW 59500,'CIMD OAuth member authority drift.',1;
DECLARE @C4bEdition int=CONVERT(int,SERVERPROPERTY('EngineEdition'));
IF @C4bEdition IS NULL OR @C4bEdition NOT IN(2,3,4,5,8) THROW 59500,'Unknown OAuth SQL platform.',1;
IF EXISTS(SELECT 1 FROM sys.database_principals p JOIN @C4bMembers a ON a.Id=p.principal_id WHERE p.authentication_type<>CASE WHEN @C4bEdition=5 THEN 2 ELSE 1 END) THROW 59500,'CIMD authentication type drift.',1;
IF EXISTS(SELECT 1 FROM sys.database_principals WHERE owning_principal_id IN(SELECT Id FROM @C4bMembers) OR owning_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')))
 OR EXISTS(SELECT 1 FROM sys.types WHERE is_user_defined=1 AND (principal_id IN(SELECT Id FROM @C4bMembers) OR principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1'))))
 OR EXISTS(SELECT 1 FROM sys.certificates WHERE principal_id IN(SELECT Id FROM @C4bMembers) OR principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')))
 OR EXISTS(SELECT 1 FROM sys.asymmetric_keys WHERE principal_id IN(SELECT Id FROM @C4bMembers) OR principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')))
 OR EXISTS(SELECT 1 FROM sys.assemblies WHERE principal_id IN(SELECT Id FROM @C4bMembers) OR principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1'))) THROW 59500,'CIMD securable ownership drift.',1;
IF (SELECT COUNT(*) FROM sys.security_predicates p JOIN sys.security_policies sp ON sp.object_id=p.object_id WHERE OBJECT_NAME(p.target_object_id) IN('AiCimdAuthorizationV1','AiCimdKeyBindingV1','AiCimdAssertionReplayV1') AND sp.object_id=OBJECT_ID('sec.TenantFilter') AND sp.is_enabled=1 AND sp.is_schema_bound=1 AND p.predicate_definition COLLATE Latin1_General_100_BIN2=N'([sec].[fn_FilterByTenant]([ShaleClientId]))')<>9
 OR (SELECT COUNT(*) FROM sys.security_predicates WHERE OBJECT_NAME(target_object_id) IN('AiCimdAuthorizationV1','AiCimdKeyBindingV1','AiCimdAssertionReplayV1'))<>9 THROW 59500,'CIMD OAuth RLS drift.',1;
IF EXISTS(SELECT 1 FROM sys.triggers t WHERE OBJECT_NAME(t.parent_id) IN(SELECT Name FROM @C4bObjects) AND t.name NOT IN(SELECT Name FROM @C4bModules)) THROW 59500,'Unreviewed CIMD OAuth trigger.',1;
IF @C4bEdition<>5 BEGIN DECLARE @C4bServerCheck nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4bServerCheck; END;

DECLARE @C4bCatalog nvarchar(max)=N'';
SET @C4bCatalog=@C4bCatalog+(SELECT CONCAT(o.name,N':',o.type,N':',o.principal_id,N':',m.execute_as_principal_id,N':',m.uses_ansi_nulls,N':',m.uses_quoted_identifier,N':',CASE WHEN o.name=N'AiCimdResolveCodeV1' THEN N'CREATE PROCEDURE dbo.AiCimdResolveCodeV1 @Hash varbinary(max),@External nvarchar(max),@Issuer nvarchar(max),@Resource nvarchar(max)
 WITH EXECUTE AS OWNER
 AS BEGIN
 SET NOCOUNT ON;
 IF @@TRANCOUNT<>0 OR (@@OPTIONS & 2)<>0 OR SESSION_CONTEXT(N''ShaleClientId'') IS NOT NULL OR SESSION_CONTEXT(N''PrincipalUserId'') IS NOT NULL OR @Hash IS NULL OR DATALENGTH(@Hash)<>32 THROW 59501,''Neutral resolver required.'',1;
 SELECT x.ShaleClientId,x.UserId FROM dbo.AiCimdAuthorizationV1 x WHERE x.CodeHash=@Hash
 AND x.ExternalClientId=@External COLLATE Latin1_General_100_BIN2 AND DATALENGTH(x.ExternalClientId)=DATALENGTH(@External)
 AND x.Issuer=@Issuer COLLATE Latin1_General_100_BIN2 AND DATALENGTH(x.Issuer)=DATALENGTH(@Issuer)
 AND x.Resource=@Resource COLLATE Latin1_General_100_BIN2 AND DATALENGTH(x.Resource)=DATALENGTH(@Resource);
 END;' WHEN o.name=N'AiCimdResolveRefreshV1' THEN N'CREATE PROCEDURE dbo.AiCimdResolveRefreshV1 @Hash varbinary(max),@External nvarchar(max),@Issuer nvarchar(max),@Resource nvarchar(max)
 WITH EXECUTE AS OWNER
 AS BEGIN
 SET NOCOUNT ON;
 IF @@TRANCOUNT<>0 OR (@@OPTIONS & 2)<>0 OR SESSION_CONTEXT(N''ShaleClientId'') IS NOT NULL OR SESSION_CONTEXT(N''PrincipalUserId'') IS NOT NULL OR @Hash IS NULL OR DATALENGTH(@Hash)<>32 THROW 59501,''Neutral resolver required.'',1;
 SELECT x.ShaleClientId,x.UserId FROM dbo.AiCimdCredentialV1 c JOIN dbo.AiCimdFamilyV1 x ON x.ShaleClientId=c.ShaleClientId AND x.SessionId=c.SessionId AND x.IntegrationId=c.IntegrationId AND x.UserId=c.UserId AND x.GrantId=c.GrantId WHERE c.CredentialHash=@Hash AND c.Kind=''REFRESH''
 AND x.ExternalClientId=@External COLLATE Latin1_General_100_BIN2 AND DATALENGTH(x.ExternalClientId)=DATALENGTH(@External)
 AND x.Issuer=@Issuer COLLATE Latin1_General_100_BIN2 AND DATALENGTH(x.Issuer)=DATALENGTH(@Issuer)
 AND x.Resource=@Resource COLLATE Latin1_General_100_BIN2 AND DATALENGTH(x.Resource)=DATALENGTH(@Resource);
 END;' WHEN o.name=N'AiCimdResolveRevocationV1' THEN N'CREATE PROCEDURE dbo.AiCimdResolveRevocationV1 @Hash varbinary(max),@External nvarchar(max),@Issuer nvarchar(max),@Resource nvarchar(max)
 WITH EXECUTE AS OWNER
 AS BEGIN
 SET NOCOUNT ON;
 IF @@TRANCOUNT<>0 OR (@@OPTIONS & 2)<>0 OR SESSION_CONTEXT(N''ShaleClientId'') IS NOT NULL OR SESSION_CONTEXT(N''PrincipalUserId'') IS NOT NULL OR @Hash IS NULL OR DATALENGTH(@Hash)<>32 THROW 59501,''Neutral resolver required.'',1;
 SELECT x.ShaleClientId,x.UserId FROM dbo.AiCimdCredentialV1 c JOIN dbo.AiCimdFamilyV1 x ON x.ShaleClientId=c.ShaleClientId AND x.SessionId=c.SessionId AND x.IntegrationId=c.IntegrationId AND x.UserId=c.UserId AND x.GrantId=c.GrantId WHERE c.CredentialHash=@Hash
 AND x.ExternalClientId=@External COLLATE Latin1_General_100_BIN2 AND DATALENGTH(x.ExternalClientId)=DATALENGTH(@External)
 AND x.Issuer=@Issuer COLLATE Latin1_General_100_BIN2 AND DATALENGTH(x.Issuer)=DATALENGTH(@Issuer)
 AND x.Resource=@Resource COLLATE Latin1_General_100_BIN2 AND DATALENGTH(x.Resource)=DATALENGTH(@Resource);
 END;' WHEN o.name=N'AiCimdImmutablePublicationV1' THEN N'CREATE TRIGGER dbo.AiCimdImmutablePublicationV1 ON dbo.AiCimdPublicationV1 AFTER UPDATE,DELETE AS BEGIN SET NOCOUNT ON;
 IF NOT EXISTS(SELECT 1 FROM inserted) OR UPDATE(ApplicationId) OR UPDATE(ApplicationRevision) OR UPDATE(MetadataDigest) OR UPDATE(Redirects) OR UPDATE(SigningKeys) THROW 59501,''CIMD publication is immutable.'',1; END;' ELSE m.definition END,N';') AS [text()] FROM sys.objects o LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE o.schema_id=SCHEMA_ID('dbo') AND o.name IN(SELECT Name FROM @C4bObjects) ORDER BY o.name FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4bCatalog=@C4bCatalog+(SELECT CONCAT(OBJECT_NAME(c.object_id),N':',c.column_id,N':',c.name,N':',c.user_type_id,N':',c.max_length,N':',c.is_nullable,N':',c.is_identity,N':',c.collation_name,N';') AS [text()] FROM sys.columns c WHERE OBJECT_NAME(c.object_id) IN(SELECT Name FROM @C4bObjects) ORDER BY c.object_id,c.column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4bCatalog=@C4bCatalog+(SELECT CONCAT(OBJECT_NAME(o.parent_object_id),N':',o.name,N':',o.type,N':',ch.definition,N':',ch.is_disabled,N':',ch.is_not_trusted,N':',dc.definition,N':',fk.referenced_object_id,N':',fk.is_disabled,N':',fk.is_not_trusted,N':',fk.delete_referential_action,N':',fk.update_referential_action,N';') AS [text()] FROM sys.objects o LEFT JOIN sys.check_constraints ch ON ch.object_id=o.object_id LEFT JOIN sys.default_constraints dc ON dc.object_id=o.object_id LEFT JOIN sys.foreign_keys fk ON fk.object_id=o.object_id WHERE OBJECT_NAME(o.parent_object_id) IN(SELECT Name FROM @C4bObjects) ORDER BY o.object_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4bCatalog=@C4bCatalog+(SELECT CONCAT(f.constraint_object_id,N':',f.constraint_column_id,N':',f.parent_column_id,N':',f.referenced_column_id,N';') AS [text()] FROM sys.foreign_key_columns f WHERE OBJECT_NAME(f.parent_object_id) IN(SELECT Name FROM @C4bObjects) ORDER BY f.constraint_object_id,f.constraint_column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4bCatalog=@C4bCatalog+(SELECT CONCAT(i.object_id,N':',i.name,N':',i.is_unique,N':',i.is_disabled,N':',i.filter_definition,N':',c.column_id,N':',c.key_ordinal,N':',c.is_included_column,N';') AS [text()] FROM sys.indexes i JOIN sys.index_columns c ON c.object_id=i.object_id AND c.index_id=i.index_id WHERE OBJECT_NAME(i.object_id) IN(SELECT Name FROM @C4bObjects) ORDER BY i.object_id,i.index_id,c.index_column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4bCatalog=@C4bCatalog+(SELECT CONCAT(p.target_object_id,N':',p.object_id,N':',p.predicate_definition,N':',p.predicate_type,N':',p.operation,N';') AS [text()] FROM sys.security_predicates p WHERE OBJECT_NAME(p.target_object_id) IN(SELECT Name FROM @C4bObjects) ORDER BY p.target_object_id,p.security_predicate_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4bCatalog=@C4bCatalog+(SELECT CONCAT(p.class,N':',p.major_id,N':',p.minor_id,N':',p.grantee_principal_id,N':',p.grantor_principal_id,N':',p.permission_name,N':',p.state,N';') AS [text()] FROM sys.database_permissions p WHERE p.class=1 AND OBJECT_NAME(p.major_id) IN(SELECT Name FROM @C4bObjects) OR p.grantee_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdOAuthNeutralV1'),DATABASE_PRINCIPAL_ID('AiCimdMetadataPublisherV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthBrowserV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthIssuerV1'),DATABASE_PRINCIPAL_ID('AiCimdOAuthResolverV1')) ORDER BY p.class,p.major_id,p.minor_id,p.grantee_principal_id,p.permission_name FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4bCatalog=@C4bCatalog+(SELECT CONCAT(t.name,N':',t.parent_id,N':',t.is_disabled,N':',t.is_instead_of_trigger,N':',e.type,N':',e.is_first,N':',e.is_last,N':',CASE WHEN t.name=N'AiCimdImmutablePublicationV1' THEN N'CREATE TRIGGER dbo.AiCimdImmutablePublicationV1 ON dbo.AiCimdPublicationV1 AFTER UPDATE,DELETE AS BEGIN SET NOCOUNT ON;
 IF NOT EXISTS(SELECT 1 FROM inserted) OR UPDATE(ApplicationId) OR UPDATE(ApplicationRevision) OR UPDATE(MetadataDigest) OR UPDATE(Redirects) OR UPDATE(SigningKeys) THROW 59501,''CIMD publication is immutable.'',1; END;' ELSE m.definition END,N';') AS [text()] FROM sys.triggers t LEFT JOIN sys.trigger_events e ON e.object_id=t.object_id LEFT JOIN sys.sql_modules m ON m.object_id=t.object_id WHERE OBJECT_NAME(t.parent_id) IN(SELECT Name FROM @C4bObjects) ORDER BY t.object_id,e.type FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
DECLARE @C4bFingerprint binary(32)=HASHBYTES('SHA2_256',@C4bCatalog);
IF ISNULL((SELECT OAuthSource FROM @CimdEvidence),0x)<>0x1a97ff3087f8a0f6a56d214ee34b41c8f1c819180c71c843aa91ef9341831528 OR ISNULL((SELECT OAuthBefore FROM @CimdEvidence),0x)<>@C4bBefore OR ISNULL((SELECT OAuthCatalog FROM @CimdEvidence),0x)<>@C4bFingerprint THROW 59500,'CIMD OAuth receipt drift.',1;
